<style>
.catalog-editor{max-width:1080px;margin:auto;color:var(--text-primary)}.catalog-editor section,.catalog-editor details{border:1px solid var(--border-glass);border-radius:16px;padding:20px;margin:16px 0;background:var(--bg-card)}.catalog-editor h2{font-size:21px;font-weight:700;margin:0 0 12px}.catalog-editor h3{font-size:17px;font-weight:600;margin:14px 0}.catalog-editor label{display:block;margin:9px 0;font-size:14px}.catalog-editor input,.catalog-editor textarea,.catalog-editor select{display:block;width:100%;padding:10px;border:1px solid var(--border-glass);border-radius:8px;background:var(--bg-glass-input);color:var(--text-primary)}.catalog-editor textarea{min-height:90px}.catalog-editor input[type=checkbox]{display:inline;width:auto}.catalog-editor button,.catalog-editor .action{display:inline-block;background:#2563eb;color:white;padding:9px 16px;border-radius:8px;margin:8px 4px 0 0}.catalog-editor .fields{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:12px}.catalog-editor summary{cursor:pointer;font-weight:650}.catalog-editor .danger{background:#9f1239}.catalog-editor .ghost{background:transparent;border:1px solid currentColor;color:inherit}.catalog-editor small{font-size:12px}.catalog-editor .batch{border-left:3px solid #6366f1;padding:12px;margin:16px 0}.catalog-editor .inquiry{border-bottom:1px solid var(--border-glass);padding:16px 0}
</style>